add(10,0x7227,'NumberToDecimal','преобразовать число калькулятора в десятичные цифры','DE буфер назначения, использует пятьбайтное поле #72DE и десятьбайтный массив цифр #72E3, через калькулятор последовательно получает десять разрядов, подавляет ведущие нули, записывает ASCII0..9 без нулевого терминатора, DE после последней цифры')
add(10,0x72ED,'CaptureAnimatedTile','сохранить фон и создать анимированный объект4на4знакоместа','BC индекс объекта, умножается на4 для #74F7, DE буфер фона, #7341 возвращает объект, задаются тип4 и четыре кадра из ресурса #80DB, в+5 сохраняется текущий банк, +6/+7 адрес фона')
add(10,0x76BC,'DrawMenuCursor','нарисовать указатель меню с пиксельным смещением','разница младших3бит X прежней позиции #79CA и новой #79CC определяет циклический сдвиг пикселей и маски #7980/#79A5, затем8строк по3байта рисуются #7722')
add(10,0x76FB,'ScreenPixelAddress','вычислить адрес байта экрана по пиксельным координатам','B строка пикселей, C X, HL=#4000+((B AND#C0)*32)+((B AND7)*256)+((B AND#38)*4)+(C>>3), BC сохранён')
add(10,0x7722,'CursorMaskedByte','наложить один байт указателя в пределах пиксельной области','при H<#58 экран=(экран AND(IY)) OR(IX), затем HL,IX,IY увеличиваются даже для пропущенного байта')
add(10,0x7735,'SaveCursorBackground','сохранить фон под указателем меню','позиция #79CC, восемь пиксельных строк по3байта копируются в #79FE, всего24байта')
add(10,0x7750,'RestoreCursorBackground','восстановить фон под старой позицией указателя','позиция #79CA, восемь пиксельных строк по3байта берутся из #79FE')
add(10,0x776D,'SelectMenuItem','управлять указателем и выбрать прямоугольный пункт меню','IX описатель меню, +0 число областей, +1..4 границы перемещения, +5/+6 начальная пиксельная позиция, с+7 идут прямоугольники по4байта в знакоместах, #787E определяет активный пункт, #78D6 меняет его атрибуты, ввод через #791E, сохранение фона через #7735/#7750')
add(10,0x787E,'HitTestMenu','найти прямоугольник меню под пиксельным указателем','IX+7 начало четырёхбайтных прямоугольников [left,top,right,bottom] в знакоместах, #79CC позиция в пикселях, границы слева/сверху включены, справа/снизу исключены, A номер1..N и IY прямоугольник, при отсутствии A=0,IY=0')
add(10,0x78D6,'InvertMenuItem','поменять местами INK и PAPER прямоугольного пункта меню','IY [left,top,right,bottom] в знакоместах, для каждого атрибута сохраняет FLASH/BRIGHT и меняет младшую и среднюю тройки бит, повторный вызов восстанавливает исходный цвет')
add(10,0x791E,'WaitMenuInput','дождаться клавиши либо Kempston для меню','ROM #028E возвращает E, #FF означает отсутствие клавиши, затем порт#1F, fire возвращает#27, направления ищутся в таблице #793B, при неизвестном ненулевом значении поиск не ограничен')
add(10,0x7950,'CursorUp','сдвинуть указатель меню на пиксель вверх','старый Y=#79CB, сравнивается с верхней границей IX+2, при допустимости новый Y-1 сохраняется #79CD')
add(10,0x795C,'CursorDown','сдвинуть указатель меню на пиксель вниз','старый Y=#79CB, сравнивается с нижней границей IX+4, при допустимости новый Y+1 сохраняется #79CD')
add(10,0x7968,'CursorLeft','сдвинуть указатель меню на пиксель влево','старый X=#79CA, сравнивается с левой границей IX+1, при допустимости новый X-1 сохраняется #79CC')
add(10,0x7974,'CursorRight','сдвинуть указатель меню на пиксель вправо','старый X=#79CA, сравнивается с правой границей IX+3, при допустимости новый X+1 сохраняется #79CC')
add(10,0x7980,'ShiftCursorRight','циклически сдвинуть вправо24битные строки указателя и маски','A число сдвигов,16строк по3байта в #79CE..#79FD, крайний правый бит возвращается слева, #7A16 увеличивается на каждый выполненный сдвиг')
add(10,0x79A5,'ShiftCursorLeft','циклически сдвинуть влево24битные строки указателя и маски','A число сдвигов,16строк по3байта #79CE..#79FD в обратном порядке, крайний левый бит возвращается справа, #7A16 уменьшается на каждый сдвиг')
add(10,0x7A17,'SumArmyField22','накопить взвешенную сумму поля22описателей отрядов','начинает с0на стеке калькулятора, HL список трёхбайтных записей, B число записей, для каждого ID!=0 передаёт количествоBC и 16битное поле IX+22/+23 на стек, выполняет калькуляторную комбинацию, текущий банк учитывается #7A49, игровое имя величины не установлено','partial')
add(10,0x7A4E,'SelectThreshold','определить одну из четырёх категорий по порогам','IX база таблицы, читает три16битных порога со смещений4,8,12, сравнивает HL с каждым, возвращает A=1..4, HL и IX сохранены')
add(10,0x7A74,'IndexFourBytes','сместить IX к четырёхбайтной записи с индексом A','IX=IX+4*A, BC сохранён')
add(10,0x7A80,'NthName','найти строку имени в списке с нулевыми разделителями','таблица начинается после #69BB, A номер1.., пропускается Aнулевых терминаторов, DE возвращает начало следующей строки, HL,BC,AF сохранены')
add(10,0x7A94,'ClearTwoFlags','обнулить два связанных байта таблиц','#7AA4 даёт IX=#6A72+A, записывает0поIX и IX+25, IX сохранён')
add(10,0x7AA4,'IndexFlagArray','получить указатель IX=#6A72+A','BC сохранён, индекс A расширяется нулём в B')
add(10,0x7AB0,'ArmyWeightedFormula','рассчитать величину армии по полю22описателей','пять трёхбайтных записей #6A1E, количество и 16битное поле IX+22/+23 передаются ROM калькулятору, участвует константа100, конкретное игровое название результата пока не доказано','partial')
add(10,0x7AEF,'UnitFlags','прочитать пару флагов описателя отряда','A ID, возвращает DE из полей13/14описателя SOLDIERS, сохраняет исходный банк, IX,BC,AF')
add(10,0x7B0B,'MarkMapObjects','пометить занятые клетки карты для групп объектов','последовательно выбирает банки0/1 и группы указателей #6B79,#6AE9,#6AF9,#6B09,#6B19,#6B29 и др, задаёт размеры области BC и шаг записиDE, вызывает #7B97 для текущего континента')
add(10,0x7B97,'MarkObjectGroup','установить бит7карты под активными записями группы','A=#6A2D выбирает четырёхбайтную запись группы, оттуда указатель и количество, объекты с бит0поля0сброшенным размечаются прямоугольником заданного размера через #7BE3, адресная структура и размеры записаны в самомодифицируемые операнды #7BC6/#7BC8/#7BD9')
add(10,0x7BE3,'MarkMapCell','установить бит7байта клетки стратегической карты','BC координаты, сохраняет банк, выбирает карту #80AE, адрес #80B4, SET7,(HL), восстанавливает банк')
add(10,0x7C71,'DirectionBetween','определить одно из восьми направлений от BC к DE','разности E-C и D-B сохраняются #7D1A/#7D1B, знак и отношение абсолютных разностей обрабатываются с ROM калькулятором, A возвращает код направления, DE адрес соответствующего названия в списке после #7D1B, HL,BC,IX,IY сохранены')
add(10,0x7D6B,'QuantityDescription','выбрать словесное описание величины HL','таблица16битных порогов после #7D94, A увеличивается до порога не меньше HL, затем выбирается одно из нуль-терминированных названий после #7DAF, DE адрес текста, HL и IX сохранены')
add(10,0x7E55,'PrintArmyBrief','вывести краткий список состава армии','IY трёхбайтные записи, A число записей, BC место вывода, для каждой непустой записи количество передаётся #7D6B для словесной оценки, #7EA7 формирует имя отряда, #7117 печатает сообщение #7E9F, следующая строка увеличивает B')
add(10,0x7EA7,'FormatUnitName','сформировать имя типа отряда со специальным окончанием','A ID описателя #8036, в #7EE9 копируется первая часть имени до последнего символа перед пробелом либо0, затем добавляется строка-окончание из списка #7EF7 по ID, буфер заканчивается0')
add(10,0x7F40,'MoveTowardTarget','преобразовать направление к цели в команду движения героя','BC=#6A2E текущая позиция, DE=#69D5 цель, #7C71 возвращает направление A, код из таблицы #7F56 передаётся обработчику #8A31')
add(10,0x7F5F,'FindNearestObject','найти ближайшую активную запись выбранной группы','D выбирает16байтный блок указателей от #6AD9, E континент через #7A74, A шаг исходной записи, BC опорные координаты, HL координаты исключаемой записи, сравнивает квадрат расстояния dx²+dy², IX ближайшая запись, минимум #7FEC и указатель #7FEE')
add(10,0x7FF0,'DistanceRounded','вычислить расстояние между координатами BC и DE','модули разностей по8бит, #801F возводит их в квадрат, сумма передаётся ROM калькулятору и затем #6D76, BC результат, точное округление зависит от ROM токенов после #8010','partial')
add(10,0x801F,'SquareByte','возвести беззнаковый байт A в квадрат','8шаговое умножение shift-add, HL=A*A, DE и BC сохранены')
add(10,0x80DB,'AnimatedSpriteAddress','выбрать банк и начало четырёхкадрового графического ресурса','A<10 даёт C=6, HL=#D700+1024*A, A>=10 даёт C=7, HL=#BC00+1024*(A-9), функция сохраняет DE,BC,AF кроме выходного C')
add(10,0x84ED,'PlaceViewLayer','поставить графический слой только на текущем континенте и в области обзора','A континент сравнивается #6A2D, #8652 проверяет BC, позиция относительно #853F преобразуется в запись экранной сетки с шагами160/20, флаги и графические адреса задаются самомодифицируемыми операндами #852D/#8534/#8536','partial')
add(10,0x8543,'PlaceObjectGroup','разместить прямоугольные объекты группы в локальном окне','IX таблица четырёхбайтных указателей по континентам, DE шаг исходных записей, BC размеры объекта сохраняются в #8578/#857B, HL исходный графический шаблон, перебирает активные записи и видимые клетки через #8652','partial')
add(10,0x85D0,'PlaceSingleCells','разместить одноклеточные записи группы в локальном окне','IX группа указателей, DE шаг записей, HL и BC сохраняются в операндах, для активных записей с координатами внутри #8652 вычисляется экранный объект относительно #853F и записывается описание слоя','partial')
add(10,0x8652,'InLocalView','проверить попадание координат BC в прямоугольник локального окна','левая/верхняя границы #853F/#8540, правая/нижняя #8541/#8542, все границы включены, carry=1 внутри, carry=0 снаружи')
add(10,0x8672,'RunOwnCastle','загрузить и выполнить обработчик своего замка','A=21, #6C3B переносит модуль, CALL #B200')
add(10,0x867D,'TerrainCategoryA','преобразовать младшие шесть бит байта местности по таблице порогов','A AND#3F, пары порог/результат после #868A, выбирается результат первого порога строго больше A, HL сохранён')
add(10,0x8697,'TerrainCategoryB','преобразовать местность по второй таблице порогов','A AND#3F, пары порог/результат после #86A4, выбирается результат первого порога строго больше A, HL сохранён')
add(10,0x86B1,'RemainingControl','вычислить остаток допустимого количества выбранного типа отряда','A ID, #86EA даёт BC базового предела, ищет тотже ID в пяти трёхбайтных записях #6A1E, если найдено существующее количество, уменьшает предел на него, регистры кроме BC сохранены','partial')
add(10,0x86EA,'ControlLimit','рассчитать численный предел типа отряда из поля героя и таблицы','BC=#6A02 передаётся ROM, байт по #6AD3+A второй операнд, последовательность калькулятора #05,#27,#38, #6D76 возвращает BC, остальные сохранённые регистры восстановлены')
add(10,0x8712,'BottomDialogFrame','нарисовать окно в нижней части экрана','BC=#0E00, DE=#081E, #73FE строит рамку с атрибутомA')
add(10,0x871C,'NeedMoreMoney','вывести сообщение о нехватке денег','A=#42 для #8712, затем #7117 печатает по BC=#1208 строку #872B «Денежки, денежки-то где ?»')
add(10,0x87D1,'FindOwnerRecord','найти активную запись с заданным владельцем','вход B сравнивается с полем+19, до80записей по35байт в логическом банке0 от #C000, проверяется сброшенный бит0поля0, zero отражает найденное совпадение, все изменённые регистры явно восстанавливаются, указатель IX наружу не возвращается')
add(10,0x88FA,'StoreBattleArmy','преобразовать боевые записи обратно в исходный состав армии','IX до5боевых записей по18байт в банке3, IY целевой массив записей по3байта в банкеC, сначала очищает Bисходных записей, ID переносится напрямую, пятибайтное количество преобразуется ROM в BC и записывается +1/+2, исходный банк восстановлен')
add(10,0x896D,'ArmyMood','оценить совместимость типа отряда с составом армии','B ID оцениваемого отряда, C дополнительный параметр, HL список до5ID, DE шаг записей, в банке3 используется матрица от #CA40 со строкой25байт и индексомID, значение#FF завершает с результатом#FF, нулевое значение снижает базовый результат, поле17описателя может увеличить либо уменьшить итог, A оценка настроения')
add(10,0x89E0,'DecreaseHeroField','уменьшить16битное поле героя #6A02 с насыщением0','ROM формула использует число2 и пятибайтные поля #656C,#6567, токены #05,#04,#27, результатBC вычитается из #6A02, при заёме записывается0')
add(10,0x8A08,'IncreaseHeroField','увеличить16битное поле героя #6A02 с насыщением#FFFF','ROM формула использует число2 и поля #6567,#656C в обратном порядке к #89E0, токены#05,#04,#27, результатBC прибавляется, при переносе записывается#FFFF')
add(10,0x8A31,'ApplyMoveCode','применить уже полученный код движения к позиции героя','входA, BC загружается #6A2E, восемь кодов направлений вызывают ограничивающие процедуры #8BDD/#8BF2/#8BF9/#8C15, затем общая проверка #8AA5, используется и автодвижением #7F40')
add(10,0x8BDD,'MapMoveUp','уменьшить строку героя в пределах рабочей части карты','при B=2 переход #8BE4 обрабатывает запрет шага, иначе DEC B, нижняя допустимая строка2')
add(10,0x8BF2,'MapMoveDown','увеличить строку героя в пределах рабочей части карты','при B=#61 переход #8BE4, иначе INC B, верхняя допустимая строка97')
add(10,0x8BF9,'MapMoveLeft','уменьшить столбец героя и повернуть его влево','при C=2 переход #8BE4, иначе DEC C, в #6A33 сбрасывается бит3, при режиме1 также сбрасывается бит4')
add(10,0x8C15,'MapMoveRight','увеличить столбец героя и повернуть его вправо','при C=#9E переход #8BE4, иначе INC C, в #6A33 ставится бит3, при режиме1 также ставится бит4')
add(10,0x8C31,'GetMoveTerrainMask','получить маску по текущему байту местности','A=#8BD9, преобразование #867D, результатL')
add(10,0x8C39,'FilterArmyOnTerrain','отфильтровать армию по маске местности и обновить записи','нулевой L немедленно завершает, маскаL патчится в AND по #8C5F, при объекте в текущей клетке проверяет флагиE каждого отряда через #7AEF, несовместимый ID обнуляется, список уплотняется #807E, затем аналогичные проверки продолжаются','partial')
add(10,0x8CD1,'FindMapObject','определить тип объекта в координатах #8D29','проверяет специальные позиции #6A44/#6A4B для текущего континента, возвращает C=10/11 при совпадении, иначе бит7карты и девять групп из таблицы #8D41, #8D6E ищет запись, C=1..9 тип группы, C=0 отсутствие объекта')
add(10,0x8D6E,'FindObjectRecord','найти активную запись группы, покрывающую координату HL','сначала бит7карты по HL, затем IX указатели текущего континента и количество, DE шаг, B/C размеры записи на карте, сравниваются координаты+1/+2 с областью, при совпадении A!=0 и IX запись, иначе A=0')
add(10,0x8DDA,'UpdateNearbyObjects','обработать группы объектов в радиусе трёх клеток героя','границы прямоугольника сохраняются #9292/#9294, обрезаются B0..99,C0..160, группы выбираются по #6A2D, далее выполняются обработчики перемещения и взаимодействий с текущим составом армии','partial')
add(10,0x9173,'InNearbyRectangle','проверить координаты DE относительно ближайшей области героя','нижние границы #9292/#9293, верхние #9294/#9295, все включены, carry=1 внутри, carry=0 снаружи')
add(10,0x9193,'CompareArmyStrength','сопоставить взвешенные величины двух составов армии','сначала пять записей #6A1E, затем входные HL/B, #91B6 вызывает суммирование #7A17 в банке1, калькулятор получает токен05 и константу2, затем #6DDA возвращает численные флаги, IX,IY сохранены','partial')
add(10,0x91B6,'SumArmyBank1','вычислить сумму полей армии из банка1','A=1, #6D2F, затем #7A17, входHL/B задаёт список трёхбайтных записей')
add(10,0x91BF,'SetObjectFacing','изменить бит6флагов объекта по коду направления','A=1 либо5 сохраняет флаг, A2..4 устанавливает бит6 IX+0, A6..8 сбрасывает бит6')
add(10,0x91D1,'CandidatesUp','сформировать три варианта шага вверх','IY массив трёх записей [0,X,Y], уменьшает байты+2,+4,+5,+8 и увеличивает+7, получается центрвверх и две соседние диагонали')
