add(10,0x9245,'DispatchCandidateDirection','построить три возможных шага объекта и вызвать обработчик направления','A1..8, IY база таблицы слов, выбирает адрес по IY+2*A, кладёт в стек сначала #9270 затем выбранный адрес, создаёт три записи [0,IX+1,IX+2] по #92B6, IY=#92B6, RET передаёт управление выбранному обработчику, его RET возвращается в #9270')
add(10,0x9270,'ClassifyCandidates','заполнить тип местности у трёх возможных шагов','продолжение стекового диспетчера #9245, три записи [тип,C,B] по #92B6, #80C4 читает карту по координатам+1/+2, #867D преобразует байт местности в маску, она записывается в поле0, IY шагает по3байта')
add(10,0x92CB,'MoveNearbySpecialGroup','обработать перемещения группы #6B69 около героя','прямоугольник±3клетки обрезается границами100на161, выбирается список текущего континента по #6B69, направление к герою определяется #7C71, #9245 формирует три варианта шага по второй таблице, дальнейшие проверки выбирают пригодную клетку','partial')
add(10,0x944A,'RefreshMainPanels','перерисовать верхнюю строку и боковую панель игры','верхняя рамка #73FE, обязательная проверяемая очистка #6B8D, строка #9525 по BC=#0112, дата через #9468, подробности героя через #957C')
add(10,0x9468,'PrintDate','разобрать счётчик дней и вывести календарную дату','поле #6A36, повторные вычитания#0162 и таблица длин периодов #94BB, печать числа дня по BC=#010C и названия через #70E3/#94C8, точные имена периодов зависят от встроенной таблицы')
add(10,0x94C8,'PrintZeroText','вывести строку с нулевым терминатором','DE адрес, BC положение, каждый байт выводится #70C5, C и DE увеличиваются, нулевой байт завершает')
add(10,0x94D2,'PrintU16','вывести16битное число HL без ведущих нулей','при HL=0 выводит0, иначе последовательные вычитания10000,1000,100,10,1 из #951B, самомодифицируемый JP #9503 подавляет первые нули, символы через #70C5, C сдвигается по каждому разряду')
add(10,0x957C,'RefreshHeroPanel','обновить боковую панель героя, расходы и рейтинг','рамка BC=#0414, обязательная #6B8D, портрет144байта из логического банка4 по #EF30, сообщения #96AE/#96F6, вывод включает «Расход», «Наличные», «Рейтинг», численные расчёты через калькулятор и #ADBF')
add(10,0x9704,'AdvanceGameTime','продвинуть время игры и выполнить периодические расчёты','прибавляет стоимость шага #69D7 к дробной части #6A35, перенос увеличивает дни #6A36, без нового дня вызывает #A5AE сA=0, при новом дне продолжается восстановление ресурсов, расчёты армии, регулярные расходы и события, строки #9CD0..#9E5C описывают жалование, корабль и пожертвования')
add(10,0x9E6D,'ClearLeftPanel','очистить основную область слева от боковой панели','BC=#0400, DE=#1414, A=0, #73CF обнуляет пиксели и атрибуты')
add(10,0x9E78,'StackTroopCost','передать стоимость отряда на стек калькулятора','IY трёхбайтная запись армии, поID читается16битное поле24/25описателя SOLDIERS, умножается на количество+1/+2 токеном04, токен31 дублирует результат, регистры восстановлены')
add(10,0x9EA5,'SumExpenseEntries','сложить отмеченные статьи расходов','семь записей по6байт от #9C7F, бит7первого байта включает следующее пятибайтное число в сумму, на стеке сначала0, токен0F сложение, результат сохраняется в #9C6B')
add(10,0x9ECA,'UpdateTroopDevelopment','повышать либо понижать типы отрядов по счётчикам','при бите7 #6565 выходит, иначе увеличивает счётчики #6A72+ID, для пяти записей армии сравнивает второй счётчик+25 с полем40описателя и основной счётчик с полем41, поля19/20задают новыйID, исходная запись обнуляется, количество переносится #A056, показываются разные сообщения о долгих странствиях/битвах либо отсутствии сражений')
add(10,0xA056,'AddTroops','добавить количество BC к типу отряда A в армии героя','уплотняет пять записей #6A1E через #807E, находит совпадающийID либо первую пустую запись, для новогоID #7A94 очищает два счётчика, записываетID и прибавляет16битное количествоBC')
add(10,0xA082,'RegenerateResourcePools','пополнить численные запасы с ограничением максимума','герой #6A04 +=#6A08 с максимумом#6A06, затем744активные записи по22байта в банке1 от #C000, поля+3/+4 увеличиваются на+5/+6 с пределом15000, далее15записей по28байт от #CCCB банка3, текущие+22/+23 увеличиваются на+26/+27 с максимумом+24/+25, общий ограничитель #A0FC')
add(10,0xA0FC,'AddClampedU16','прибавить BC к HL с верхней границей DE','если сложение переносит16бит либо сумма>=DE, HL=DE, иначе HLсумма, при сравнении carry от ADD равен0')
add(10,0xA107,'WeekEvent','обработать наступление новой недели и связанное изменение типа существ','исходноеBC делится повторными вычитаниями19, остаток+7 записывается #A203 какIDтипа, сообщение «Прошла неделя», поля38 и18описателя определяют параметры, далее обработка записей через #A205','partial')
add(10,0xA205,'GrowSelectedTroop','увеличить количество заданного типа в трёхбайтной записи','если IDпоIX совпадает #A203, количествоHL увеличивается на частное от деления исходного количества на #A204 через повторное вычитание, запись+1/+2 обновляется, IX всегда сдвигается на3')
add(10,0xA235,'RefreshTownForces','обновить армии объектов группы #6AF9','логический банк0, текущий континент, у активных записей с вероятностным фильтром через #7C0D очищаются девятьбайт гарнизона по смещению17, далее заполняются выбранные виды и количества, шаг исходной записи26','partial')
add(10,0xA2E0,'CheckArmyControl','проверить неподконтрольные отряды и обработать недовольство','пять записей #6A1E, #86EA даёт предельное количество, превышение и случайный результат3из диапазона3 запускают диалог, используются стоимость, деньги и варианты «Хорошо, я заплачу»/«Ничего не получите», возможен бой либо уход, точные все ветви требуют отдельной игровой проверки','partial')
add(10,0xA5AE,'CastleAttackEvents','обработать угрозу нападения и бой за принадлежащий герою замок','входA сохранён #A700, #69D8=1, используется состояние #6AAA и признак #6565, случайно выбирается подходящая запись80замков банка0, строки сообщают о готовящемся нападении, сроке4дня, защите гарнизоном, захвате и возможности перенестись, поле#6AAC хранит связанную запись','partial')
add(10,0xAC78,'RefreshFourObjectGroups','периодически пополнить содержимое четырёх групп объектов','счётчик #AD30 уменьшается, работа одинразна4вызова, таблица четырёх указателей #AD28, текущий континент выбирает список, у активных записей с нулевыми полями4/5 генерируется новое содержимое через #7C0D, шаги и шаблоны выбираются по таблицам','partial')
add(10,0xAD31,'PlaceNearbyRecords','разместить новые записи около объектов группы #6B39','для активных записей просматривает3на3окрестность, #80C4 исключает занятые клетки и ненулевой типместности, координаты нового содержимого выбираются через #7C0D, обновляются связанные записи и карта','partial')
add(10,0xADBF,'SumCastleIncome','сложить доход принадлежащих герою замков на четырёх континентах','начальное0на стеке калькулятора, группа #6AE9, активные записи с владельцем+19равным0 считаются своими, #AE1A возвращает доходBC каждой, токен0F суммирует, возвращается число калькулятора')
add(10,0xAE1A,'CastleIncome','рассчитать доход замка с учётом ближайших городов','IY запись замка, A континент, группа городов #6AF9, базовый доход100, города учитываются при абсолютной разнице координат<=17пообеимосям, отдельная проверка бита1поля+1 и поля17 может исключить город, добавляется350либо450взависимости от полей15/16, результатBC')
